export function lineChart(root,values){const w=700,h=220,p=30,max=Math.max(...values,1)*1.1;const pts=values.map((v,i)=>[p+i*(w-2*p)/(values.length-1),h-p-v/max*(h-2*p)]);const line=pts.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' '),area=`${line} L${pts.at(-1)[0]},${h-p} L${p},${h-p} Z`;const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.classList.add('chart');const defs=document.createElementNS(ns,'defs'),g=document.createElementNS(ns,'linearGradient');g.id='chartGradient';g.setAttribute('x2','0%');g.setAttribute('y2','100%');for(const [offset,opacity] of [['0%','.36'],['100%','0']]){const stop=document.createElementNS(ns,'stop');stop.setAttribute('offset',offset);stop.setAttribute('stop-color','currentColor');stop.setAttribute('stop-opacity',opacity);g.append(stop)}defs.append(g);svg.append(defs);for(let i=0;i<5;i++){const l=document.createElementNS(ns,'line');l.setAttribute('x1',p);l.setAttribute('x2',w-p);l.setAttribute('y1',p+i*(h-2*p)/4);l.setAttribute('y2',p+i*(h-2*p)/4);l.setAttribute('class','grid-line');svg.append(l)}for(const [d,c] of [[area,'area'],[line,'line']]){const path=document.createElementNS(ns,'path');path.setAttribute('d',d);path.setAttribute('class',c);svg.append(path)}pts.forEach(([x,y])=>{const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx',x);circle.setAttribute('cy',y);circle.setAttribute('r',4);circle.setAttribute('fill','var(--accent)');svg.append(circle)});root.replaceChildren(svg)}
